type MenuItem = { id: number; name: string; category: string; price_cents: number; available: number; sends_to_kitchen?: number; description?: string; descriptionNote?: string; descriptionSources?: { title: string; url: string }[] };
type Line = { menu_item_id: number; name?: string; qty: number; unit_price_cents?: number; sends_to_kitchen?: number };
type Order = { version?: number; discount_json?: string; discount_cents?: number; visit_id?: string; id: number; client_id?: string; station: string; receipt_no: number; receipt_label?: string; created_at: string; items: Line[]; total_cents: number; subtotal_cents: number; tax_cents: number; cash_tendered_cents?: number; change_cents?: number; status: string; kitchen_status: string; edit_count: number; void_reason?: string; voided_at?: string; staff_name?: string };
